-- Phase 23a — learn_brand_list: the owner's brand-name priority sheet (Brands.xlsx, 1,283 rows)
-- Destination: db/phase23a_learn_brand_list.sql
-- One row per sheet row; sheet_id = the sheet's own ID column (not a PCID). brand_pcid / generic_pcid / *_match / status /
-- review_note are filled by phase 23b. Read-only to the public (RLS read policy, no write grants).
create table if not exists public.learn_brand_list (
  sheet_id           integer primary key,
  importance         text not null check (importance in ('High','Medium','Low')),
  brand_name         text not null,
  generic_name       text not null,
  therapeutic_domain text,
  clinical_context   text,
  brand_pcid         bigint references public.entities(pcid) on update cascade,
  generic_pcid       bigint references public.entities(pcid) on update cascade,
  brand_match        text,
  generic_match      text,
  created_at         timestamptz not null default now()
);
create unique index if not exists learn_brand_list_name_uidx on public.learn_brand_list (lower(brand_name));
create index if not exists learn_brand_list_brand_idx on public.learn_brand_list (brand_pcid);
create index if not exists learn_brand_list_generic_idx on public.learn_brand_list (generic_pcid);
alter table public.learn_brand_list enable row level security;
drop policy if exists learn_brand_list_read on public.learn_brand_list;
create policy learn_brand_list_read on public.learn_brand_list for select using (true);
revoke all on public.learn_brand_list from anon, authenticated;
grant select on public.learn_brand_list to anon, authenticated;

-- Data as loaded 2026-10-29 (brand names as typed in the sheet; later corrections are in 23b)
on conflict (sheet_id) do nothing;
on conflict (sheet_id) do nothing;
on conflict (sheet_id) do nothing;
on conflict (sheet_id) do nothing;
